import java.io.*; import java.util.*; public class TestClass { static class Node { int id; long sum; int count; int parent; Node(int id, long sum, int count, int parent) { this.id = id; this.sum = sum; this.count = count; this.parent = parent; } } public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; StringTokenizer st = new StringTokenizer(line); int n = Integer.parseInt(st.nextToken()); int q = Integer.parseInt(st.nextToken()); long[] vals = new long[n + 1]; st = new StringTokenizer(br.readLine()); for (int i = 1; i <= n; i++) vals[i] = Long.parseLong(st.nextToken()); List<Integer>[] adj = new ArrayList[n + 1]; for (int i = 1; i <= n; i++) adj[i] = new ArrayList<Integer>(); for (int i = 0; i < n - 1; i++) { st = new StringTokenizer(br.readLine()); int u = Integer.parseInt(st.nextToken()); int v = Integer.parseInt(st.nextToken()); adj[u].add(v); adj[v].add(u); } StringBuilder sb = new StringBuilder(); for (int i = 0; i < q; i++) { st = new StringTokenizer(br.readLine()); int x = Integer.parseInt(st.nextToken()); long k = Long.parseLong(st.nextToken()); sb.append(solve(x, k, n, vals, adj)).append("\n"); } System.out.print(sb); } private static int solve(int start, long k, int n, long[] vals, List<Integer>[] adj) { if (vals[start] >= k) return 1; Queue<Node> queue = new LinkedList<Node>(); queue.add(new Node(start, vals[start], 1, -1)); while (!queue.isEmpty()) { Node curr = queue.poll(); for (int neighbor : adj[curr.id]) { if (neighbor != curr.parent) { long nextSum = curr.sum + vals[neighbor]; if (nextSum >= k) return curr.count + 1; queue.add(new Node(neighbor, nextSum, curr.count + 1, curr.id)); } } } return -1; } }